import { test, expect } from '@playwright/test';

test.describe('Google Account Connection to User Profile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should successfully connect Google account to user profile', async ({ page }) => {
    // Verify connection button is visible
    const connectButton = page.getByRole('button', { name: /connect account/i });
    await expect(connectButton).toBeVisible();

    // Click connect button
    await connectButton.click();

    // Verify modal opens
    const modal = page.locator('[data-testid="google-auth-modal"]');
    await expect(modal).toBeVisible();

    // Verify email input is visible
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();

    // Verify password input is visible
    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();

    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Fill email and password
    await emailInput.fill('user@example.com');
    await passwordInput.fill('password123');

    // Click login button
    await loginButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/account connected/i);
    await expect(successMessage).toBeVisible();

    // Verify user profile is updated
    const profileName = page.getByText(/John Doe/i);
    await expect(profileName).toBeVisible();

    // Verify user is logged in
    const userName = page.getByText(/Welcome, John Doe/i);
    await expect(userName).toBeVisible();

    // Verify user is redirected to profile page
    await expect(page).toHaveURL(/profile/i);
  });

  test('should display error when Google account is not found', async ({ page }) => {
    // Click connect button
    const connectButton = page.getByRole('button', { name: /connect account/i });
    await connectButton.click();

    // Verify modal opens
    const modal = page.locator('[data-testid="google-auth-modal"]');
    await expect(modal).toBeVisible();

    // Verify error message is visible
    const errorMessage = page.getByText(/account not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify connection button is still visible
    await expect(connectButton).toBeVisible();

    // Verify user is not logged in
    const userName = page.getByText(/Welcome, John Doe/i);
    await expect(userName).not.toBeVisible();

    // Verify user is still on profile page
    await expect(page).toHaveURL(/profile/i);
  });
});
